// This code has been fully generated by an AI.
// Gemeinsam für Bühne, Bedienung und Spieler: Verbindung zum Server, Aktionen, Abbildung Kamera → Canvas.
//
// Die Seiten kommen vom lokalen Client, Spiel und Medien vom Server im LAN. Adresse, Token und Rolle
// übergibt der Client-Starter in der URL (?server=…&token=…&role=…&name=…).

export const COLORS = { 1: "#00e5ff", 2: "#ff2e88" };

export const PARAMS = new URLSearchParams(location.search);
export const SERVER = PARAMS.get("server") || location.host;
export const TOKEN = PARAMS.get("token") || "";
export const ROLE = PARAMS.get("role") || "";
export const NAME = PARAMS.get("name") || "";
export const HTTP = `http://${SERVER}`;

export function authHeaders(extra = {}) {
  return { ...extra, Authorization: `Bearer ${TOKEN}` };
}

// Medien-URLs im Zustand sind serverrelativ („/media/…“); hier liegt die Seite aber woanders.
export function mediaUrl(url) {
  return url && url.startsWith("/") ? HTTP + url : url;
}

export function api(path, opts = {}) {
  return fetch(HTTP + path, { ...opts, headers: authHeaders(opts.headers || {}) });
}

export function connect(onPacket, { frames = true, onAuthLost = null } = {}) {
  let busy = false;
  let pending = null;

  async function handle(buf) {
    busy = true;
    const view = new DataView(buf);
    const len = view.getUint32(0, true);
    const state = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 4, len)));
    let bitmap = null;
    if (buf.byteLength > 4 + len) {
      // Bild und Zustand gehören zusammen; erst nach dem Dekodieren gemeinsam zeichnen.
      bitmap = await createImageBitmap(new Blob([new Uint8Array(buf, 4 + len)], { type: "image/jpeg" }));
    }
    onPacket(state, bitmap);
    busy = false;
    if (pending) {
      const next = pending;
      pending = null;
      handle(next);
    }
  }

  function open() {
    const query = `token=${encodeURIComponent(TOKEN)}&frames=${frames ? 1 : 0}`;
    const ws = new WebSocket(`ws://${SERVER}/ws?${query}`);
    ws.binaryType = "arraybuffer";
    ws.onmessage = (e) => {
      // Rückstau verwerfen: nur das neueste Bild zählt.
      if (busy) pending = e.data;
      else handle(e.data);
    };
    ws.onclose = (e) => {
      // 4401: Server kennt diese Anmeldung nicht mehr; weiter versuchen, falls der Client sich neu anmeldet.
      if (e.code === 4401 && onAuthLost) onAuthLost();
      setTimeout(open, e.code === 4401 ? 3000 : 1000);
    };
  }
  open();
}

export async function act(name, data = {}) {
  try {
    const res = await fetch(`${HTTP}/api/${name}`, {
      method: "POST",
      headers: authHeaders({ "Content-Type": "application/json" }),
      body: JSON.stringify(data),
    });
    return await res.json();
  } catch {
    return { ok: false, message: "Server nicht erreichbar." };
  }
}

// Letterbox: Kamerabild passt ins Canvas, Seitenverhältnis bleibt. Ein Rand (`pad`) gehört zum Bild,
// die Koordinaten bleiben aber Arena-Einheiten mit (0, 0) in der Feldecke.
export function fit(canvas, frame) {
  const p = frame.pad || 0;
  const s = Math.min(canvas.width / (frame.w + 2 * p), canvas.height / (frame.h + 2 * p));
  return { s, ox: (canvas.width - frame.w * s) / 2, oy: (canvas.height - frame.h * s) / 2 };
}

export function drawFrame(ctx, v, frame, bitmap) {
  const p = frame.pad || 0;
  const [x, y] = toCanvas(v, [-p, -p]);
  ctx.drawImage(bitmap, x, y, (frame.w + 2 * p) * v.s, (frame.h + 2 * p) * v.s);
}

export function toCanvas(v, p) {
  return [v.ox + p[0] * v.s, v.oy + p[1] * v.s];
}

export function toFrame(v, x, y) {
  return [(x - v.ox) / v.s, (y - v.oy) / v.s];
}

export function pathPoly(ctx, v, pts) {
  ctx.beginPath();
  pts.forEach((p, i) => {
    const [x, y] = toCanvas(v, p);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.closePath();
}

export function resizeCanvas(canvas) {
  const r = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = Math.round(r.width * dpr);
  const h = Math.round(r.height * dpr);
  if (canvas.width !== w || canvas.height !== h) {
    canvas.width = w;
    canvas.height = h;
  }
}

// Tastenkürzel in beiden Fenstern gleich, damit die Bühne im Vollbild auch bedienbar bleibt.
export function hotkeys(getNames = () => []) {
  window.addEventListener("keydown", (e) => {
    if (e.target instanceof HTMLInputElement) {
      if (e.key === "Enter") act("start", { names: getNames() });
      return;
    }
    const map = {
      o: ["spawn", { kind: "obstacle" }],
      p: ["spawn", { kind: "powerup" }],
      k: ["shrink"],
      n: ["new_battle"],
      s: ["start", { names: getNames() }],
      1: ["ulti", { player: 1 }],
      2: ["ulti", { player: 2 }],
    };
    const hit = map[e.key] || map[e.key.toLowerCase()];
    if (!hit) return;
    e.preventDefault();
    act(hit[0], hit[1] || {});
  });
}
